corrected_code:
const { delegateToSchema } = require('@graphql-tools/delegate');
const express = require('express');
const { createHandler } = require('graphql-http/lib/use/express');
const { makeExecutableSchema } = require('@graphql-tools/schema');

const app = express();
app.use(express.json());

const resolvers = {
  Query: {
    order: async (_, { id }, context) => {
      // Enforce that order belongs to the authenticated user
      const order = await context.db.orders.findById(id);
      if (!order || order.userId !== context.user.id) {
        throw new Error('Order not found or access denied');
      }
      return order;
    }
  },
  Order: {
    customerBilling: {
      selectionSet: '{ customerId }',
      resolve(order, args, context, info) {
        return delegateToSchema({
          schema: context.billingSubschema,
          operation: 'query',
          fieldName: 'billingProfileById',
          args: { customerId: order.customerId },
          context,
          info
        });
      }
    }
  }
};

const gatewaySchema = makeExecutableSchema({ typeDefs: require('./schemaDefs'), resolvers });
app.all('/graphql', createHandler({ schema: gatewaySchema }));

module.exports = app;
